questions.text:
¿Qué se mostrará en la aplicación al renderizar el siguiente componente?

function App() {
    return (
        <View>
            <Text>Hola mundo</Text>
        </View>
    );
}

¿Qué se mostrará al renderizar el siguiente código?

function Usuario(props) {
    return (
        <Text>{props.nombre}</Text>
    );
}

function App() {
    return <Usuario nombre="María" />;
}

Si incrementar() se ejecuta una vez partiendo de contador = 0, ¿cuál será el nuevo valor?

const [contador, setContador] = useState(0);

const incrementar = () => {
    setContador(contador + 1);
};

¿Qué contenido se muestra inicialmente?

const [nombre, setNombre] = useState("Carlos");

return (
    <Text>{nombre}</Text>
);

¿Cuál es el propósito principal del siguiente código?

const respuesta = await fetch(
    "https://api.ejemplo.com/productos"
);

const datos = await respuesta.json();
